        //             "symbol": "BTCUSD",
        //             "exchange": "CRYPTO",
        //             "asset_class": "crypto",
        //             "asset_marginable": false,
        //             "qty": "0.000207296",
        //             "avg_entry_price": "80037",
        //             "side": "long",
        //             "market_value": "16.592345",
        //             "cost_basis": "16.59135",
        //             "unrealized_pl": "0.000995",
        //             "unrealized_plpc": "0.00006",
        //             "current_price": "80041.8",
        //             "qty_available": "0.000207296"
        //         }
